{
  "paper_title": "K-means-sharp: modified centroid update for outlier-robust k-means clustering",
  "authors_year": "Peter O. Olukanmi and Bhekisipho Twala, 2017",
  "research_question": "How to preserve the structure, simplicity, and efficiency of classical k-means while addressing its non-robustness to outliers without requiring user intervention or prior knowledge of the number of outliers?",
  "context": "Real-world datasets commonly contain noise and outliers, which skew classical k-means clustering because it is a least-squares method. Traditional outlier detection methods often rely on separate modules, user-supplied parameters, or complex graph constructions.",
  "methods": [
    "Modifying only the centroid update step in classical k-means to automatically detect and exempt putative outliers",
    "Using a global point-to-centroid distance threshold T derived from the distribution of point-to-centroid distances and robust scale estimation (median absolute deviation)",
    "Setting the distance threshold T to 3 sigma, where sigma equals 1.4826 multiplied by the median absolute deviation (MAD_e)",
    "Evaluating performance across 10 datasets (2 standard datasets: Iris and Ruspini, and 4 outlier-contaminated versions of each with 5%, 10%, 15%, and 20% gross errors)",
    "Running experiments over 100 runs per dataset with 50 iterations per run"
  ],
  "main_findings": [
    "Given identical initializations, k-means# yields lower mean squared error than classical k-means for all datasets tested",
    "On outlier-contaminated datasets, k-means# achieves an overall average accuracy of 90.4% and precision of 86.8%",
    "Outlier detection metrics for k-means# reach maximum values of 99.2% accuracy, 100% precision, 90.0% recall, and 92.9% F1-score"
  ],
  "assumptions": [
    "K-means assumes a Gaussian data distribution, meaning nearly all inliers (precisely 99.73%) will have point-to-centroid distances within 3 standard deviations from the population mean",
    "Sigma can be unbiasedly estimated by 1.4826 times the median absolute deviation (MAD_e)"
  ],
  "limitations_explicit": [
    "Rare cases occur where random initial centroid selection results in zero true positives (such as when all initial centroids are outliers), leading to undefined precision and F1-score",
    "The within-cluster error is no longer monotonically decreasing due to the inliers set changing in every iteration"
  ],
  "potential_open_questions": [
    {
      "question": "What is the sensitivity of the algorithm to the choice of the number of standard deviations used to determine the inlier-outlier distinction threshold?",
      "why_unresolved": "The choice of 3 standard deviations plays a role in performance, and varying this value is expected to introduce trade-offs among various performance metrics.",
      "evidence": "It is expected that our choice of 3 standard deviations as the boundary for inlier point-to-centroid distance, plays a role in the performance of the algorithm. We expect trade-offs among the various performance metrics as this value is varied.",
      "sections": [
        "Section V",
        "Section VI"
      ]
    },
    {
      "question": "Would the use of cluster-specific thresholds instead of a single global threshold improve performance?",
      "why_unresolved": "Cluster-specific thresholds may improve performance but would also introduce some increase in computational cost.",
      "evidence": "Furthermore, the use of cluster-specific thresholds in contrast to a single global threshold, may improve performance, and is therefore worth exploring, although this will introduce some increase in computational cost.",
      "sections": [
        "Section VI"
      ]
    }
  ],
  "candidate_hypotheses": [
    {
      "hypothesis": "Incorporating special seeding methods into k-means# will eliminate rare cases of zero true positives caused by poor initial centroid selection.",
      "rationale": "Bad initializations (such as selecting all outliers as initial centroids) cause zero true positives, a drawback inherited from classical k-means that can be mitigated by seeding.",
      "evidence": "The problem could be caused by a bad set of randomly selected initial centroids, such as when all initial centroids are outliers. This drawback is inherited from k-means... It can be addressed by incorporating special seeding methods into the algorithm, such as those discussed in Section III.",
      "sections": [
        "Section V.C"
      ]
    },
    {
      "hypothesis": "Incorporating existing k-means improvements designed to address other drawbacks into k-means# will yield increased overall robustness.",
      "rationale": "Because k-means# preserves the original k-means structure, it is structurally compatible with other modular enhancements.",
      "evidence": "Lastly, since k-means# preserves the original k-means structure, it can easily benefit from many existing k-means improvements designed to address other drawbacks. Incorporation of some of these should yield increased robustness.",
      "sections": [
        "Section VI"
      ]
    }
  ]
}

{
  "paper_title": "An adaptive outlier removal aided k-means clustering algorithm",
  "authors_year": "Nawaf H.M.M. Shrifan, Muhammad F. Akbar, Nor Ashidi Mat Isa, 2022",
  "research_question": "How to improve the clustering accuracy and centroids convergence of the k-means algorithm by mitigating outliers' influences and utilizing a new distance metric?",
  "context": "Data clustering is widely used in pattern recognition, image segmentation, bioinformatics, and COVID-19 distribution analysis, but standard partitioning algorithms like k-means perform poorly in the presence of outliers and are sensitive to the choice of distance metric.",
  "methods": [
    "Adapted Tukey's rule for outlier removal that accounts for data distribution skewness independently per attribute",
    "A new angle-based distance metric utilizing ratio coefficients and root mean square error (RMSE)",
    "A modified k-means clustering algorithm that applies the adapted Tukey's rule recursively during centroid updates without removing entire data points",
    "Validation on nine standard multivariate datasets from the UCI repository and comparison against standard k-means, HCA, FFA, evolutionary algorithms, DBSCAN, and k-means#"
  ],
  "main_findings": [
    "The proposed modified k-means improved the overall clustering accuracy up to 80.57% across nine standard multivariate datasets.",
    "The adapted Tukey's rule reduced the overall iteration number for centroid convergence by 50% compared to the standard Tukey's rule.",
    "The proposed distance metric outperformed standard Euclidean, cosine, and correlation metrics in overall average accuracy."
  ],
  "assumptions": [
    "Input data attributes can be normalized to positive values between 1 and 90 to avoid division by zero.",
    "Data skewness can be detected by counting the number of data points along the mean value's right and left sides.",
    "Outliers can be mitigated by adjusting boundaries per attribute during centroid calculation while keeping all data points in the clustering assignment phase."
  ],
  "limitations_explicit": [
    "Real-time clustering is challenged by the extra processing time added by the recursive outlier removal step.",
    "The proposed distance metric is limited to real values greater than zero, requiring data normalization pre-processing.",
    "Datasets with a very high number of possible classes/clusters degrade the clustering accuracy of the modified k-means."
  ],
  "potential_open_questions": [
    {
      "question": "How can the time complexity of the adapted Tukey's rule for outlier removal be reduced for big data clustering?",
      "why_unresolved": "The recursive application of the adapted Tukey's rule adds significant processing time compared to standard k-means, making big data and real-time application challenging.",
      "evidence": "Section 6 notes that real-time clustering is hindered by the outlier removal step adding processing time, and Section 7 states that improving run-time for big data clustering by reducing time complexity is a future work item.",
      "sections": [
        "6. Challenges and limitations",
        "7. Conclusion and future work"
      ]
    },
    {
      "question": "Can the adapted Tukey's rule and new distance metric be successfully integrated into other partitioning algorithms like fuzzy c-means and k-medoids?",
      "why_unresolved": "The current paper primarily tests the modifications on the standard k-means algorithm.",
      "evidence": "Section 7 states: In future work, the adapted Tukey's rule and the new distance metric will be applied to various clustering algorithms such as fuzzy c-means and k-medoids.",
      "sections": [
        "7. Conclusion and future work"
      ]
    }
  ],
  "candidate_hypotheses": [
    {
      "hypothesis": "Applying the adapted Tukey's rule and new distance metric to alternative clustering algorithms such as fuzzy c-means or k-medoids will similarly improve their clustering accuracy and convergence rate.",
      "rationale": "Since fuzzy c-means and k-medoids also suffer from outlier influence and distance metric sensitivity, decoupling outlier mitigation from point assignment should yield performance gains analogous to those seen in modified k-means.",
      "evidence": "Section 7 proposes applying these techniques to fuzzy c-means and k-medoids as future work.",
      "sections": [
        "7. Conclusion and future work"
      ]
    }
  ]
}

